const url = 'http://192.168.8.124:8080/remote.php/dav/files/admin/RAG_Inbox/';
const propfindBody = `<?xml version="1.0"?><d:propfind xmlns:d="DAV:"><d:prop><d:displayname/><d:resourcetype/><d:getcontenttype/></d:prop></d:propfind>`;

const user = $env.NEXTCLOUD_USER;
const pass = $env.NEXTCLOUD_PASS;
if (!user || !pass) {
  throw new Error('NEXTCLOUD_USER or NEXTCLOUD_PASS environment variables are missing');
}
const authHeader = 'Basic ' + Buffer.from(`${user}:${pass}`).toString('base64');

const response = await this.helpers.httpRequest({
  method: 'PROPFIND',
  url: url,
  headers: {
    'Authorization': authHeader,
    'Depth': '1',
    'Content-Type': 'application/xml'
  },
  body: propfindBody,
  returnFullResponse: true
});

const xmlText = response.body;
const files = [];
const responseRegex = /<d:response>([\s\S]*?)<\/d:response>/g;
let match;
const prefix = '/remote.php/dav/files/admin/';

while ((match = responseRegex.exec(xmlText)) !== null) {
  const responseBlock = match[1];
  const hrefMatch = responseBlock.match(/<d:href>([^<]+)<\/d:href>/);
  const href = hrefMatch ? hrefMatch[1] : null;
  const resourceTypeMatch = responseBlock.match(/<d:resourcetype>([\s\S]*?)<\/d:resourcetype>/);
  const isDirectory = resourceTypeMatch && resourceTypeMatch[1].includes('<d:collection/>');

  if (href && !isDirectory) {
    const relativePath = href.startsWith(prefix) ? href.substring(prefix.length) : href;
    const fileName = relativePath.split('/').pop();
    if (fileName && (fileName.endsWith('.md') || fileName.endsWith('.txt'))) {
      files.push({ json: { file_path: relativePath, file_name: fileName, nc_path: relativePath } });
    }
  }
}

return files;

const items = $input.all();
const allChunks = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const listNodeData = $('WebDAV List Files').itemMatching(i).json;
  const fileName = listNodeData.file_name || 'unknown.md';
  const ncPath = listNodeData.nc_path || '/RAG_Inbox/';

  let text = '';
  if (item.binary && item.binary.data) {
    text = Buffer.from(item.binary.data, 'base64').toString('utf8');
  } else if (item.json.data && typeof item.json.data === 'string') {
    text = item.json.data;
  }

  const chunkSize = 800;
  const overlap = 100;
  const step = chunkSize - overlap;
  const totalChunks = Math.max(1, Math.ceil(text.length / step));

  let idx = 1;
  for (let pos = 0; pos < text.length; pos += step) {
    allChunks.push({
      json: {
        chunk_text: text.substring(pos, pos + chunkSize),
        file_name: fileName,
        chunk_index: idx,
        total_chunks: totalChunks,
        nc_path: ncPath
      },
      pairedItem: { item: i }
    });
    idx++;
  }
}

return allChunks;

const chunkData = $('Code: Chunking').item.json;
const fileName = chunkData.file_name || 'unknown_file';
const chunkIndex = chunkData.chunk_index || 1;
const ncPath = chunkData.nc_path || '/RAG_Inbox/';
const chunkText = chunkData.chunk_text || '';
const totalChunks = chunkData.total_chunks || null;
const embedding = $json.data?.[0]?.embedding || $json.embedding || [];

function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

return {
  json: {
    qdrant_id: generateUUID(),
    vector: embedding,
    payload: {
      chunk_id: `${fileName}_chunk${chunkIndex}`,
      file_name: fileName,
      chunk_index: chunkIndex,
      text_content: chunkText,
      document_type: "auto_ingested",
      language: "it",
      status: "active",
      source_reference: ncPath,
      nextcloud_path: ncPath,
      ingested_at: new Date().toISOString()
    },
    nc_path: ncPath,
    file_name: fileName,
    total_chunks: totalChunks
  }
};

const items = $input.all();
const map = {};

for (let i = 0; i < items.length; i++) {
  const meta = $('Code: Prep Qdrant Payload').itemMatching(i).json;
  const key = meta.file_name;
  if (!map[key]) {
    map[key] = {
      file_name: meta.file_name,
      nc_path: meta.nc_path,
      total_chunks: meta.total_chunks,
      success_count: 0
    };
  }
  map[key].success_count += 1;
}

return Object.values(map).map(f => ({
  json: {
    file_name: f.file_name,
    nc_path: f.nc_path,
    total_chunks: f.total_chunks,
    success_count: f.success_count,
    complete: f.total_chunks != null ? f.success_count >= f.total_chunks : true
  }
}));

const fileName = $json.file_name;
const ncPath = $json.nc_path;
const sourceUrl = `http://192.168.8.124:8080/remote.php/dav/files/admin/${ncPath}`;
const destinationUrl = `http://192.168.8.124:8080/remote.php/dav/files/admin/RAG_Inbox/Processed/${fileName}`;

const user = $env.NEXTCLOUD_USER;
const pass = $env.NEXTCLOUD_PASS;
if (!user || !pass) {
  throw new Error('NEXTCLOUD_USER or NEXTCLOUD_PASS environment variables are missing');
}
const authHeader = 'Basic ' + Buffer.from(`${user}:${pass}`).toString('base64');

try {
  // MOVE nativo WebDAV (operazione atomica)
  await this.helpers.httpRequest({
    method: 'MOVE',
    url: sourceUrl,
    headers: {
      'Authorization': authHeader,
      'Destination': destinationUrl,
      'Overwrite': 'T'
    }
  });

  return [{ json: { success: true, moved_file: fileName, status: 'moved_successfully' } }];
} catch (error) {
  if (error.response?.status === 404 || error.statusCode === 404) {
    return [{ json: { success: true, moved_file: fileName, status: 'already_processed' } }];
  }
  throw error;
}
